class Solution {
public:
    int minimumOR(vector<vector<int>>& grid) {
        vector<int> cur = {0};
        for (auto& row : grid) {
            vector<int> nxt;
            for (int v : cur)
                for (int x : row) nxt.push_back(v | x);
            sort(nxt.begin(), nxt.end());
            nxt.erase(unique(nxt.begin(), nxt.end()), nxt.end());
            cur = nxt;
        }
        return *min_element(cur.begin(), cur.end());
    }
};

