class Solution {
    public int minimumOR(int[][] grid) {
        Set<Integer> cur = new HashSet<>();
        cur.add(0);
        for (int[] row : grid) {
            Set<Integer> nx = new HashSet<>();
            for (int v : cur) for (int x : row) nx.add(v | x);
            cur = nx;
        }
        int ans = Integer.MAX_VALUE;
        for (int v : cur) ans = Math.min(ans, v);
        return ans;
    }
};

