    int minimumOR(vector<vector<int>>& grid) {
        int ans = 0;
        for (int b = 17; b >= 0; b--) {
            int m = ans | (1 << b);
            bool ok = true;
            for (auto& row : grid) {
                bool f = false;
                for (int x : row) if ((x & m) == x) { f = true; break; }
                if (!f) { ok = false; break; }
            }
            if (ok) ans = m;
        }
        return ans;
    }
};

